local Saddler = {}
local PRODUCTS = {
    saddle = { name = "Sedlo", leatherCost = 5, woodCost = 2, metalCost = 1, time = 7, cost = 100, speedBonus = 0.10, description = "Konjsko sedlo." },
    bridle = { name = "Uzda", leatherCost = 2, metalCost = 1, time = 3, cost = 40, controlBonus = 5, description = "Uzda za konja." },
    harness = { name = "Oprema", leatherCost = 8, woodCost = 3, metalCost = 2, time = 10, cost = 200, loadBonus = 50, description = "Vprega za voz." },
    saddlebags = { name = "Sedlarne vreče", leatherCost = 3, time = 4, cost = 60, cargoBonus = 30, description = "Vreče za prtljago." },
    war_saddle = { name = "Bojno sedlo", leatherCost = 6, woodCost = 3, metalCost = 3, time = 12, cost = 300, speedBonus = 0.15, combatBonus = 10, prestige = 5, description = "Oklepno sedlo za viteze." },
    royal_saddle = { name = "Kraljevsko sedlo", leatherCost = 10, woodCost = 3, metalCost = 5, goldCost = 2, time = 20, cost = 1000, speedBonus = 0.25, prestige = 20, description = "Najboljše sedlo za kralja." },
}
local BUILDINGS = {
    workshop = { name = "Sedlarska delavnica", cost = { gold = 300, wood = 100, leather = 30 }, upkeep = 10, qualityBonus = 5 },
    tack_shop = { name = "Konjska oprema", cost = { gold = 800, wood = 200, stone = 100, leather = 50 }, upkeep = 20, qualityBonus = 15 },
    leather_mill = { name = "Usnjarnica", cost = { gold = 600, wood = 200, stone = 100 }, upkeep = 15, qualityBonus = 10 },
    royal_saddlery = { name = "Kraljevska sedlarna", cost = { gold = 4000, wood = 400, stone = 600, leather = 100 }, upkeep = 80, qualityBonus = 35, prestigeBonus = 15 },
}
Saddler.leatherStock = 15; Saddler.woodStock = 10; Saddler.metalStock = 8; Saddler.goldStock = 3
Saddler.productStock = {}; Saddler.buildings = {}; Saddler.saddler = nil; Saddler.activeMaking = {}; Saddler.totalProducts = 0; Saddler.dayTimer = 0
function Saddler.init() Saddler.leatherStock=15; Saddler.woodStock=10; Saddler.metalStock=8; Saddler.goldStock=3; Saddler.productStock={}; Saddler.buildings={}; Saddler.saddler=nil; Saddler.activeMaking={}; Saddler.totalProducts=0; Saddler.dayTimer=0; print("[Saddler] Royal Saddler & Tack Maker System initialized (6 products, 4 buildings)") end
function Saddler.hireSaddler(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Saddler.saddler={name=n or ("Sedlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sedlar najet: %s (spretnost: %d)",Saddler.saddler.name,s),"success") end; return true end
function Saddler.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Saddler.build(id) local ok,e=Saddler.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Saddler.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Saddler.getQualityBonus() local b=0; for _,bd in ipairs(Saddler.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Saddler.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.leatherCost and Saddler.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.woodCost and Saddler.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.metalCost and Saddler.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.goldCost and Saddler.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #Saddler.buildings==0 then return false,"Potrebna delavnica" end; if not Saddler.saddler then return false,"Potreben sedlar" end; return true end
function Saddler.make(pt) local ok,e=Saddler.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.leatherCost then Saddler.leatherStock=Saddler.leatherStock-d.leatherCost end; if d.woodCost then Saddler.woodStock=Saddler.woodStock-d.woodCost end; if d.metalCost then Saddler.metalStock=Saddler.metalStock-d.metalCost end; if d.goldCost then Saddler.goldStock=Saddler.goldStock-d.goldCost end; local t=d.time; if Saddler.saddler then t=math.max(1,t-math.floor(Saddler.saddler.skill/12)) end; table.insert(Saddler.activeMaking,{id="saddle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,speedBonus=d.speedBonus or 0,combatBonus=d.combatBonus or 0,controlBonus=d.controlBonus or 0,loadBonus=d.loadBonus or 0,cargoBonus=d.cargoBonus or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function Saddler.completeMaking(m) local q=1.0+(Saddler.getQualityBonus()/100); if Saddler.saddler then q=q+(Saddler.saddler.skill/200) end; q=math.min(2.0,q); Saddler.productStock[m.productType]=(Saddler.productStock[m.productType] or 0)+1; Saddler.totalProducts=Saddler.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if Saddler.saddler then Saddler.saddler.itemsMade=Saddler.saddler.itemsMade+1; if math.random()<0.15 then Saddler.saddler.skill=math.min(100,Saddler.saddler.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sedlo izdelano: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Saddler.update(dt) if not _G.state then return end; Saddler.dayTimer=Saddler.dayTimer+dt; if Saddler.dayTimer>=30 then Saddler.dayTimer=0; for i=#Saddler.activeMaking,1,-1 do local m=Saddler.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Saddler.completeMaking(m); table.remove(Saddler.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Saddler.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Saddler.saddler then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Saddler.getStats() return {leatherStock=Saddler.leatherStock,woodStock=Saddler.woodStock,metalStock=Saddler.metalStock,productStock=Saddler.productStock,numBuildings=#Saddler.buildings,hasSaddler=Saddler.saddler~=nil,saddlerName=Saddler.saddler and Saddler.saddler.name or "—",saddlerSkill=Saddler.saddler and Saddler.saddler.skill or 0,activeMaking=#Saddler.activeMaking,totalProducts=Saddler.totalProducts} end
return Saddler
